 private void applyAdminMode(){if(!isAdmin())return;tabs.getSelectionModel().select(adminTab);adminWorkspaceTitle.setText(adminMaintenanceMode?"教师信息维护":"教师信息管理");managementNavButton.getStyleClass().removeAll("student-side-button","student-side-button-active");maintenanceNavButton.getStyleClass().removeAll("student-side-button","student-side-button-active");managementNavButton.getStyleClass().add(adminMaintenanceMode?"student-side-button":"student-side-button-active");maintenanceNavButton.getStyleClass().add(adminMaintenanceMode?"student-side-button-active":"student-side-button");teacherTable.refresh();}
