 @FXML private void searchTeachers(){String id=input(teacherSearchIdField.getText()).toLowerCase(),name=input(teacherSearchNameField.getText()).toLowerCase(),keyword=input(teacherSearchKeywordField.getText()).toLowerCase();filteredTeachers=new ArrayList<>(teachers.stream().filter(t->input(t.getTeacherId()).toLowerCase().contains(id)).filter(t->input(t.getName()).toLowerCase().contains(name)).filter(t->String.join(" ",input(t.getCollege()),input(t.getDepartment()),input(t.getTitle()),input(t.getEmploymentStatus())).toLowerCase().contains(keyword)).toList());teacherCurrentPage=1;refreshTeacherPage();}
 private int teacherPageCount(){return Math.max(1,(filteredTeachers.size()+PAGE_SIZE-1)/PAGE_SIZE);} private void refreshTeacherPage(){teacherCurrentPage=Math.max(1,Math.min(teacherCurrentPage,teacherPageCount()));int from=Math.min((teacherCurrentPage-1)*PAGE_SIZE,filteredTeachers.size()),to=Math.min(from+PAGE_SIZE,filteredTeachers.size());teacherTable.getItems().setAll(filteredTeachers.subList(from,to));teacherTable.refresh();teacherPageField.setText(String.valueOf(teacherCurrentPage));teacherPageSummaryLabel.setText("共"+filteredTeachers.size()+"条  共"+teacherPageCount()+"页");updateTeacherSelection();} @FXML private void firstTeacherPage(){teacherCurrentPage=1;refreshTeacherPage();} @FXML private void previousTeacherPage(){if(teacherCurrentPage>1)teacherCurrentPage--;refreshTeacherPage();} @FXML private void nextTeacherPage(){if(teacherCurrentPage<teacherPageCount())teacherCurrentPage++;refreshTeacherPage();} @FXML private void lastTeacherPage(){teacherCurrentPage=teacherPageCount();refreshTeacherPage();} @FXML private void goTeacherPage(){try{teacherCurrentPage=Integer.parseInt(teacherPageField.getText().trim());}catch(Exception e){statusLabel.setText("请输入有效页码");}refreshTeacherPage();}
 @FXML private void clearTeacherId(){teacherSearchIdField.clear();searchTeachers();}@FXML private void clearTeacherName(){teacherSearchNameField.clear();searchTeachers();}@FXML private void clearTeacherKeyword(){teacherSearchKeywordField.clear();searchTeachers();}
 @FXML private void resetTeacherSearch(){teacherSearchIdField.clear();teacherSearchNameField.clear();teacherSearchKeywordField.clear();searchTeachers();}
 @FXML private void searchTeacherReviews(){String id=input(reviewTeacherSearchField.getText()).toLowerCase(),status=input(reviewStatusSearchField.getText()).toLowerCase();boolean completed=completedTeacherReviewButton.isSelected();requestTable.setItems(FXCollections.observableArrayList(reviewRequests.stream().filter(r->completed?r.getStatus()!=StudentChangeStatus.PENDING:r.getStatus()==StudentChangeStatus.PENDING).filter(r->input(r.getTeacherId()).toLowerCase().contains(id)).filter(r->(teacherReviewStatus(r.getStatus())+" "+input(r.getStatus())).toLowerCase().contains(status)).toList()));requestTable.refresh();}
 @FXML private void clearReviewTeacher(){reviewTeacherSearchField.clear();searchTeacherReviews();}@FXML private void clearReviewStatus(){reviewStatusSearchField.clear();searchTeacherReviews();}@FXML private void resetTeacherReviewSearch(){reviewTeacherSearchField.clear();reviewStatusSearchField.clear();searchTeacherReviews();}
 @FXML private void returnOverview(){if(editing)cancelEdit();tabs.getSelectionModel().select(isAdmin()?adminTab:overviewTab); }
 @FXML private void showBase(){scrollTo(baseSection);}@FXML private void showJob(){scrollTo(jobSection);}@FXML private void showContact(){scrollTo(contactSection);}
 private void scrollTo(VBox node){if(detailScroll==null||node==null)return;double total=detailScroll.getContent().getBoundsInLocal().getHeight()-detailScroll.getViewportBounds().getHeight();detailScroll.setVvalue(total<=0?0:node.getBoundsInParent().getMinY()/total);}
 private void receiveOverview(Message m){Platform.runLater(()->{if(!ok(m)){statusLabel.setText(m.getMessage());return;}overview=data(m,"overview",TeacherOverviewVO.class);render();});}
 private void render(){TeacherChangeRequest progress=overview==null?null:(overview.getPendingRequest()!=null?overview.getPendingRequest():overview.getLatestRequest());reviewStatusPane.showRequest(progress==null?null:progress.getStatus(),progress==null?null:progress.getSubmitTime());Teacher t=displayTeacher();if(t==null){statusLabel.setText("暂无教师档案");return;}String name=show(t.getName()),initial="-".equals(name)?"师":name.substring(0,1);nameLabel.setText(name);avatarLabel.setText(initial);sideAvatarLabel.setText(initial);sideNameLabel.setText(name);sideMetaLabel.setText(show(t.getDepartment()));metaLabel.setText(String.join(" · ",show(t.getTeacherId()),show(t.getCollege()),show(t.getDepartment()),show(t.getTitle())));overviewStatusValue.setText(show(t.getEmploymentStatus()));overviewTitleValue.setText(show(t.getTitle()));overviewCollegeValue.setText(show(t.getCollege()));overviewEmployedValue.setText(t.isEmployed()?"在职":"离职");fill(baseGrid,t,BASE);fill(jobGrid,t,JOB);fill(contactGrid,t,CONTACT);renderExperiences(overview.getWorkExperiences());renderFamilyMembers(overview.getFamilyMembers());if(isAdmin())setDetailEditable(adminMaintenanceMode);statusLabel.setText(overview.getPendingRequest()==null?"教师信息已更新":"修改申请待管理员审核，当前显示修改后的内容");}
 private Teacher displayTeacher(){if(overview==null||overview.getTeacher()==null)return null;Teacher result=gson.fromJson(gson.toJson(overview.getTeacher()),Teacher.class);TeacherChangeRequest pending=overview.getPendingRequest();if(!isAdmin()&&pending!=null&&pending.getItems()!=null)for(TeacherChangeItem item:pending.getItems())try{write(result,item.getFieldName(),item.getNewValue());}catch(Exception ignored){}return result;}
 private void renderExperiences(List<TeacherWorkExperience> records){if(experienceCardContainer==null)return;selectedExperience=null;selectedExperienceCard=null;editExperienceButton.setDisable(true);deleteExperienceButton.setDisable(true);experienceCardContainer.getChildren().clear();if(records==null||records.isEmpty()){Label empty=new Label("暂无工作经历");empty.getStyleClass().add("student-info-empty-card");empty.setMaxWidth(Double.MAX_VALUE);experienceCardContainer.getChildren().add(empty);return;}for(TeacherWorkExperience record:records){GridPane grid=new GridPane();grid.getStyleClass().add("student-info-record-grid");grid.setMaxWidth(Double.MAX_VALUE);addCardField(grid,"开始年月",month(record.getStartDate()),0,0);addCardField(grid,"结束年月",record.getEndDate()==null?"至今":month(record.getEndDate()),0,1);addCardField(grid,"工作单位",record.getOrganization(),1,0);addCardField(grid,"所在部门",record.getDepartment(),1,1);addCardField(grid,"职务",record.getPosition(),2,0);addCardField(grid,"工作内容",record.getDescription(),2,1);VBox card=new VBox(grid);card.getStyleClass().add("student-info-record-card");card.setMaxWidth(Double.MAX_VALUE);card.setOnMouseClicked(event->selectExperience(record,card));experienceCardContainer.getChildren().add(card);}}
 private void addCardField(GridPane grid,String key,Object value,int row,int pair){Label k=new Label(key),v=new Label(show(value));k.getStyleClass().add("student-field-key");v.getStyleClass().add("student-field-value");v.setWrapText(true);v.setMaxWidth(Double.MAX_VALUE);grid.add(k,pair*2,row);grid.add(v,pair*2+1,row);ColumnConstraints a=new ColumnConstraints(120),b=new ColumnConstraints();if(grid.getColumnConstraints().isEmpty()){b.setHgrow(Priority.ALWAYS);grid.getColumnConstraints().addAll(a,b,new ColumnConstraints(120),new ColumnConstraints());grid.getColumnConstraints().get(3).setHgrow(Priority.ALWAYS);}}
 private void selectExperience(TeacherWorkExperience record,Pane card){if(selectedExperienceCard!=null)selectedExperienceCard.getStyleClass().remove("student-info-record-card-selected");selectedExperience=record;selectedExperienceCard=card;card.getStyleClass().add("student-info-record-card-selected");editExperienceButton.setDisable(false);deleteExperienceButton.setDisable(false);}
 private void fill(GridPane g,Teacher t,List<String> fields){prepareSixColumns(g);g.getChildren().clear();for(int i=0;i<fields.size();i++){String f=fields.get(i);Label k=new Label(title(f)),v=new Label(show(read(t,f)));k.getStyleClass().add("student-field-key");k.setAlignment(Pos.CENTER_LEFT);k.setMinWidth(136);k.setPrefWidth(136);k.setMaxWidth(136);k.setTooltip(new Tooltip(k.getText()));v.getStyleClass().add("student-field-value");v.setAlignment(Pos.CENTER_LEFT);v.setWrapText(true);v.setMinWidth(0);v.setMaxWidth(Double.MAX_VALUE);v.setTooltip(new Tooltip(v.getText()));int row=i/3,pair=i%3;g.add(k,pair*2,row);g.add(v,pair*2+1,row);}}
 private void beginGlobalEdit(){if(editing||overview==null||overview.getTeacher()==null)return;if(!isAdmin()&&overview.getPendingRequest()!=null){statusLabel.setText("当前修改申请正在审核中，审核完成后才能再次修改");return;}editableControls.clear();editing=true;fillEditable(baseGrid,BASE);fillEditable(jobGrid,JOB);fillEditable(contactGrid,CONTACT);Button cancel=new Button("取消");cancel.getStyleClass().add("btn-secondary");cancel.setOnAction(e->cancelEdit());Button submit=new Button(isAdmin()?"保存修改":"提交修改申请");submit.getStyleClass().add("btn-primary");submit.setOnAction(e->submitEdit());HBox actions=new HBox(8,cancel,submit);actions.setAlignment(Pos.CENTER_RIGHT);contactGrid.add(actions,0,(CONTACT.size()+2)/3,6,1);statusLabel.setText(isAdmin()?"全部信息已进入编辑状态，保存后直接生效":"全部信息已进入编辑状态，提交后等待审核");}
 private void fillEditable(GridPane grid,List<String> fields){prepareSixColumns(grid);grid.getChildren().clear();Teacher teacher=overview.getTeacher();for(int i=0;i<fields.size();i++){String field=fields.get(i);Label key=new Label(title(field)+(Set.of("department","education","employmentStartDate").contains(field)?" *":""));key.getStyleClass().add("student-field-key");if(Set.of("department","education","employmentStartDate").contains(field))key.setStyle("-fx-text-fill: #b91c1c;");key.setAlignment(Pos.CENTER_LEFT);key.setMinWidth(136);key.setPrefWidth(136);key.setMaxWidth(136);Control value=createEditor(field,showInput(read(teacher,field)));value.setUserData(field);value.setMinWidth(0);value.setMaxWidth(Double.MAX_VALUE);boolean allowed=isAdmin()||EDITABLE.contains(field);value.setDisable(!allowed);if(allowed)editableControls.add(value);int row=i/3,pair=i%3;grid.add(key,pair*2,row);grid.add(value,pair*2+1,row);}}
 private Control createEditor(String field,String initial){Control control;if(Set.of("idIssueDate","birthDate","partyJoinDate","employmentStartDate").contains(field)){DatePicker picker=new DatePicker();if(!initial.isBlank())try{picker.setValue(java.time.LocalDate.parse(initial));}catch(Exception ignored){}control=picker;}else if("education".equals(field)){ComboBox<String> combo=new ComboBox<>(FXCollections.observableArrayList("专科","本科","硕士研究生","博士研究生","其他"));combo.setValue(initial.isBlank()?null:initial);control=combo;}else if("idType".equals(field)){ComboBox<String> combo=new ComboBox<>(FXCollections.observableArrayList("居民身份证","港澳台居民居住证","护照","其他"));combo.setValue(initial);control=combo;}else if("householdType".equals(field)){ComboBox<String> combo=new ComboBox<>(FXCollections.observableArrayList("城镇户口","农村居民户口","集体户口","其他"));combo.setValue(initial);control=combo;}else if(Set.of("partyMember","employed").contains(field)){ComboBox<String> combo=new ComboBox<>(FXCollections.observableArrayList("是","否"));combo.setValue(Set.of("true","1","是","在职").contains(initial)?"是":"否");control=combo;}else control=new TextField(initial);control.getStyleClass().add("form-control");return control;}
 private String controlValue(Control control){if(control instanceof TextInputControl text)return text.getText().trim();if(control instanceof DatePicker date)return date.getValue()==null?"":date.getValue().toString();if(control instanceof ComboBox<?> combo)return combo.getValue()==null?"":String.valueOf(combo.getValue()).trim();return "";}
 private void cancelEdit(){editing=false;editableControls.clear();render();statusLabel.setText("已取消编辑");}
 private void submitEdit(){Teacher teacher=overview.getTeacher();Map<String,String> changed=new LinkedHashMap<>();for(Control control:editableControls){String field=String.valueOf(control.getUserData()),old=showInput(read(teacher,field)),now=controlValue(control);if(!old.equals(now))changed.put(field,now);}String department=changed.getOrDefault("department",showInput(teacher.getDepartment())),education=changed.getOrDefault("education",showInput(teacher.getEducation())),start=changed.getOrDefault("employmentStartDate",showInput(teacher.getEmploymentStartDate()));if(department.isBlank()){statusLabel.setText("所在部门不能为空");return;}if(education.isBlank()){statusLabel.setText("学历不能为空");return;}if(start.isBlank()){statusLabel.setText("入职日期不能为空");return;}if(changed.isEmpty()){statusLabel.setText("没有检测到修改内容");return;}if(isAdmin()){Teacher updated=gson.fromJson(gson.toJson(teacher),Teacher.class);try{changed.forEach((field,value)->write(updated,field,value));}catch(Exception exception){statusLabel.setText("格式错误: "+exception.getMessage());return;}service.update(updated,m->Platform.runLater(()->{statusLabel.setText(m.getMessage());if(ok(m)){editing=false;service.query(updated.getTeacherId(),this::receiveOverview);}}));}else submitChanges(teacher,changed);}
 private void prepareSixColumns(GridPane g){g.setAlignment(Pos.CENTER_LEFT);g.setHgap(12);g.setVgap(9);g.setMaxWidth(Double.MAX_VALUE);if(g.getColumnConstraints().size()==6)return;g.getColumnConstraints().clear();for(int i=0;i<6;i++){ColumnConstraints c=new ColumnConstraints();if(i%2==0){c.setMinWidth(136);c.setPrefWidth(136);c.setMaxWidth(136);c.setHgrow(Priority.NEVER);}else{c.setMinWidth(0);c.setPrefWidth(150);c.setMaxWidth(Double.MAX_VALUE);c.setHgrow(Priority.ALWAYS);}c.setFillWidth(true);g.getColumnConstraints().add(c);}}
 private void setupTables(){selectAllTeachers=new CheckBox();selectAllTeachers.setOnAction(e->{if(selectAllTeachers.isSelected())for(Teacher teacher:filteredTeachers)selectedTeacherIds.add(teacher.getTeacherId());else for(Teacher teacher:filteredTeachers)selectedTeacherIds.remove(teacher.getTeacherId());teacherTable.refresh();updateTeacherSelection();});selectCol.setGraphic(selectAllTeachers);selectCol.setCellFactory(column->new TableCell<>(){private final CheckBox checkBox=new CheckBox();{setAlignment(Pos.CENTER);checkBox.setOnAction(e->{int index=getIndex();if(index<0||index>=getTableView().getItems().size())return;Teacher teacher=getTableView().getItems().get(index);if(checkBox.isSelected())selectedTeacherIds.add(teacher.getTeacherId());else selectedTeacherIds.remove(teacher.getTeacherId());updateTeacherSelection();});}@Override protected void updateItem(Void item,boolean empty){super.updateItem(item,empty);if(empty||getIndex()>=getTableView().getItems().size())setGraphic(null);else{checkBox.setSelected(selectedTeacherIds.contains(getTableView().getItems().get(getIndex()).getTeacherId()));setGraphic(checkBox);}}});idCol.setCellValueFactory(c->s(c.getValue().getTeacherId()));nameCol.setCellValueFactory(c->s(c.getValue().getName()));collegeCol.setCellValueFactory(c->s(c.getValue().getCollege()));departmentCol.setCellValueFactory(c->s(c.getValue().getDepartment()));titleCol.setCellValueFactory(c->s(c.getValue().getTitle()));statusCol.setCellValueFactory(c->s(c.getValue().getEmploymentStatus()));teacherTable.setOnMouseClicked(e->{if(e.getClickCount()==2){Teacher t=teacherTable.getSelectionModel().getSelectedItem();if(t!=null)service.query(t.getTeacherId(),m->Platform.runLater(()->{if(ok(m)){overview=data(m,"overview",TeacherOverviewVO.class);render();tabs.getSelectionModel().select(detailTab);}else statusLabel.setText(m.getMessage());}));}});requestTeacherCol.setCellValueFactory(c->s(c.getValue().getTeacherId()));requestSubmitCol.setCellValueFactory(c->s(c.getValue().getSubmitTime()));requestStatusCol.setCellValueFactory(c->s(teacherReviewStatus(c.getValue().getStatus())));requestReviewCol.setCellValueFactory(c->s(c.getValue().getReviewTime()));requestTable.setOnMouseClicked(e->{if(e.getClickCount()==2)reviewSelected();});}
 private void setupActionColumn(){actionCol.setCellFactory(column->new TableCell<>(){private final Button button=new Button();{button.getStyleClass().add("table-action-button");button.setOnAction(e->{int index=getIndex();if(index<0||index>=getTableView().getItems().size())return;Teacher teacher=getTableView().getItems().get(index);service.query(teacher.getTeacherId(),m->Platform.runLater(()->{if(!ok(m)){statusLabel.setText(m.getMessage());return;}overview=data(m,"overview",TeacherOverviewVO.class);render();tabs.getSelectionModel().select(detailTab);}));});}@Override protected void updateItem(Void item,boolean empty){super.updateItem(item,empty);button.setText(adminMaintenanceMode?"编辑":"查看详情");setGraphic(empty||getIndex()<0||getIndex()>=getTableView().getItems().size()?null:button);}});}
 private void setDetailEditable(boolean visible){for(Button button:List.of(editButton,jobEditButton,contactEditButton)){button.setVisible(visible);button.setManaged(visible);}}
 private void loadAdmin(){service.list(m->Platform.runLater(()->{if(ok(m)){List<Teacher> x=data(m,"teachers",new TypeToken<List<Teacher>>(){}.getType());teachers=x==null?new ArrayList<>():new ArrayList<>(x);selectedTeacherIds.clear();searchTeachers();}}));service.reviews(m->Platform.runLater(()->{if(ok(m)){List<TeacherChangeRequest>x=data(m,"requests",new TypeToken<List<TeacherChangeRequest>>(){}.getType());reviewRequests=x==null?new ArrayList<>():new ArrayList<>(x);searchTeacherReviews();}}));}
 private void updateTeacherSelection(){if(selectAllTeachers!=null){long count=filteredTeachers.stream().filter(t->selectedTeacherIds.contains(t.getTeacherId())).count();selectAllTeachers.setIndeterminate(count>0&&count<filteredTeachers.size());selectAllTeachers.setSelected(!filteredTeachers.isEmpty()&&count==filteredTeachers.size());}if(selectedTeacherCountLabel!=null)selectedTeacherCountLabel.setText("已选择 "+selectedTeacherIds.size()+" 人");if(exportTeachersButton!=null)exportTeachersButton.setDisable(selectedTeacherIds.isEmpty());}
 @FXML private void exportSelectedTeachers(){List<Teacher> selected=teachers.stream().filter(t->selectedTeacherIds.contains(t.getTeacherId())).toList();if(selected.isEmpty()){AlertUtil.showWarning("请选择教师","请先勾选需要导出的教师。");return;}FileChooser chooser=new FileChooser();chooser.setTitle("导出教师信息");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("Excel 工作簿 (*.xlsx)","*.xlsx"));chooser.setInitialFileName("教师信息_"+java.time.LocalDate.now()+".xlsx");File chosen=chooser.showSaveDialog(teacherTable.getScene().getWindow());if(chosen==null)return;File output=chosen.getName().toLowerCase(Locale.ROOT).endsWith(".xlsx")?chosen:new File(chosen.getParentFile(),chosen.getName()+".xlsx");exportTeachersButton.setDisable(true);statusLabel.setText("正在导出 "+selected.size()+" 名教师的信息...");Task<Void> task=new Task<>(){@Override protected Void call()throws Exception{TeacherExcelExport.export(selected,output);return null;}};task.setOnSucceeded(e->{exportTeachersButton.setDisable(false);statusLabel.setText("已导出 "+selected.size()+" 名教师的信息");AlertUtil.showInfo("导出成功","Excel 已保存至：\n"+output.getAbsolutePath());});task.setOnFailed(e->{exportTeachersButton.setDisable(false);statusLabel.setText("教师信息导出失败");Throwable error=task.getException();AlertUtil.showError("导出失败",error==null?"无法生成 Excel 文件。":"无法生成 Excel 文件：\n"+error.getMessage());});Thread worker=new Thread(task,"teacher-excel-export");worker.setDaemon(true);worker.start();}
