 @FXML private void deleteWorkExperience(){if(selectedExperience==null){statusLabel.setText("请先选择工作经历");return;}Alert alert=new Alert(Alert.AlertType.CONFIRMATION,"确定删除选中的工作经历吗？",ButtonType.OK,ButtonType.CANCEL);alert.setHeaderText(null);if(alert.showAndWait().orElse(ButtonType.CANCEL)!=ButtonType.OK)return;service.deleteWorkExperience(selectedExperience.getExperienceId(),m->Platform.runLater(()->{statusLabel.setText(m.getMessage());if(ok(m))service.overview(this::receiveOverview);}));}
 private void showWorkExperienceEditor(TeacherWorkExperience source){Dialog<ButtonType> dialog=new Dialog<>();dialog.setTitle(source==null?"新增工作经历":"编辑工作经历");GridPane grid=new GridPane();grid.setHgap(12);grid.setVgap(10);grid.setPadding(new javafx.geometry.Insets(8,12,8,12));DatePicker start=new DatePicker(),end=new DatePicker();TextField organization=new TextField(),department=new TextField(),position=new TextField(),description=new TextField();if(source!=null){if(source.getStartDate()!=null)start.setValue(source.getStartDate().toLocalDate());if(source.getEndDate()!=null)end.setValue(source.getEndDate().toLocalDate());organization.setText(input(source.getOrganization()));department.setText(input(source.getDepartment()));position.setText(input(source.getPosition()));description.setText(input(source.getDescription()));}start.setPromptText("必填");end.setPromptText("留空表示至今");Control[] controls={start,end,organization,department,position,description};String[] labels={"开始时间","结束时间","工作单位","所在部门","职务","工作内容"};Set<Integer> required=Set.of(0,2,3,4);for(int i=0;i<labels.length;i++){controls[i].setPrefWidth(360);Label caption=new Label(labels[i]);if(required.contains(i)){Label star=new Label("*");star.setStyle("-fx-text-fill: #d93025; -fx-font-weight: bold;");HBox requiredLabel=new HBox(3,caption,star);requiredLabel.setAlignment(Pos.CENTER_LEFT);grid.add(requiredLabel,0,i);}else grid.add(caption,0,i);grid.add(controls[i],1,i);}dialog.getDialogPane().setContent(grid);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);dialog.showAndWait().ifPresent(button->{if(button!=ButtonType.OK)return;try{if(start.getValue()==null)throw new IllegalArgumentException("开始时间不能为空");if(organization.getText().isBlank())throw new IllegalArgumentException("工作单位不能为空");if(department.getText().isBlank())throw new IllegalArgumentException("所在部门不能为空");if(position.getText().isBlank())throw new IllegalArgumentException("职务不能为空");if(end.getValue()!=null&&end.getValue().isBefore(start.getValue()))throw new IllegalArgumentException("结束时间不能早于开始时间");TeacherWorkExperience value=source==null?new TeacherWorkExperience():gson.fromJson(gson.toJson(source),TeacherWorkExperience.class);value.setStartDate(Date.valueOf(start.getValue()));value.setEndDate(end.getValue()==null?null:Date.valueOf(end.getValue()));value.setOrganization(organization.getText().trim());value.setDepartment(department.getText().trim());value.setPosition(position.getText().trim());value.setDescription(description.getText().trim());java.util.function.Consumer<Message> done=m->Platform.runLater(()->{statusLabel.setText(m.getMessage());if(ok(m))service.overview(this::receiveOverview);});if(source==null)service.addWorkExperience(value,done);else service.updateWorkExperience(value,done);}catch(Exception exception){statusLabel.setText("工作经历格式错误: "+exception.getMessage());}});}
 private void renderFamilyMembers(List<TeacherFamilyMember> records){if(familyCardContainer==null)return;selectedFamilyMember=null;selectedFamilyCard=null;editFamilyButton.setDisable(true);deleteFamilyButton.setDisable(true);familyCardContainer.getChildren().clear();if(records==null||records.isEmpty()){Label empty=new Label("暂无社会关系成员");empty.getStyleClass().add("student-info-empty-card");empty.setMaxWidth(Double.MAX_VALUE);familyCardContainer.getChildren().add(empty);return;}for(TeacherFamilyMember record:records){GridPane grid=new GridPane();grid.getStyleClass().add("student-info-record-grid");grid.setMaxWidth(Double.MAX_VALUE);addCardField(grid,"姓名",record.getName(),0,0);addCardField(grid,"与本人关系",record.getRelationship(),0,1);addCardField(grid,"出生年月",record.getBirthDate(),1,0);addCardField(grid,"健康状况",record.getHealthStatus(),1,1);addCardField(grid,"户口所在地",record.getRegisteredResidence(),2,0);addCardField(grid,"联系电话",record.getPhone(),2,1);addCardField(grid,"工作单位",record.getWorkplace(),3,0);addCardField(grid,"工作单位地址",record.getWorkplaceAddress(),3,1);VBox card=new VBox(grid);card.getStyleClass().add("student-info-record-card");card.setMaxWidth(Double.MAX_VALUE);card.setOnMouseClicked(e->{if(selectedFamilyCard!=null)selectedFamilyCard.getStyleClass().remove("selected");selectedFamilyMember=record;selectedFamilyCard=card;card.getStyleClass().add("selected");editFamilyButton.setDisable(false);deleteFamilyButton.setDisable(false);});familyCardContainer.getChildren().add(card);}}
