 private void showFamilyMemberEditor(TeacherFamilyMember source){Dialog<ButtonType> dialog=new Dialog<>();dialog.setTitle(source==null?"新增主要社会关系":"编辑主要社会关系");GridPane grid=new GridPane();grid.setHgap(12);grid.setVgap(10);grid.setPadding(new javafx.geometry.Insets(8,12,8,12));TextField name=new TextField(),relationship=new TextField(),residence=new TextField(),workplace=new TextField(),address=new TextField(),health=new TextField(),phone=new TextField();DatePicker birth=new DatePicker();if(source!=null){name.setText(input(source.getName()));relationship.setText(input(source.getRelationship()));if(source.getBirthDate()!=null)birth.setValue(source.getBirthDate().toLocalDate());residence.setText(input(source.getRegisteredResidence()));workplace.setText(input(source.getWorkplace()));address.setText(input(source.getWorkplaceAddress()));health.setText(input(source.getHealthStatus()));phone.setText(input(source.getPhone()));}Control[] controls={name,relationship,birth,residence,workplace,address,health,phone};String[] labels={"姓名","与本人关系","出生年月","户口所在地","工作单位","工作单位地址","健康状况","联系电话"};for(int i=0;i<labels.length;i++){controls[i].setPrefWidth(360);Label caption=new Label(labels[i]);if(Set.of(0,1,2,3,4,7).contains(i)){Label star=new Label("*");star.setStyle("-fx-text-fill: #d93025; -fx-font-weight: bold;");HBox requiredLabel=new HBox(3,caption,star);requiredLabel.setAlignment(Pos.CENTER_LEFT);grid.add(requiredLabel,0,i);}else grid.add(caption,0,i);grid.add(controls[i],1,i);}dialog.getDialogPane().setContent(grid);dialog.getDialogPane().getButtonTypes().addAll(ButtonType.OK,ButtonType.CANCEL);dialog.showAndWait().ifPresent(button->{if(button!=ButtonType.OK)return;try{if(name.getText().isBlank())throw new IllegalArgumentException("姓名不能为空");if(relationship.getText().isBlank())throw new IllegalArgumentException("与本人关系不能为空");if(birth.getValue()==null)throw new IllegalArgumentException("出生年月不能为空");if(residence.getText().isBlank())throw new IllegalArgumentException("户口所在地不能为空");if(workplace.getText().isBlank())throw new IllegalArgumentException("工作单位不能为空");if(phone.getText().isBlank())throw new IllegalArgumentException("联系电话不能为空");TeacherFamilyMember value=source==null?new TeacherFamilyMember():gson.fromJson(gson.toJson(source),TeacherFamilyMember.class);value.setName(name.getText().trim());value.setRelationship(relationship.getText().trim());value.setBirthDate(birth.getValue()==null?null:Date.valueOf(birth.getValue()));value.setRegisteredResidence(residence.getText().trim());value.setWorkplace(workplace.getText().trim());value.setWorkplaceAddress(address.getText().trim());value.setHealthStatus(health.getText().trim());value.setPhone(phone.getText().trim());java.util.function.Consumer<Message> done=m->Platform.runLater(()->{statusLabel.setText(m.getMessage());if(ok(m))service.overview(this::receiveOverview);});if(source==null)service.addFamilyMember(value,done);else service.updateFamilyMember(value,done);}catch(Exception exception){statusLabel.setText("社会关系信息格式错误: "+exception.getMessage());}});}
 private String month(Date value){return value==null?"":value.toString().substring(0,7);}private String input(Object value){return value==null?"":String.valueOf(value);}
 private void submitChanges(Teacher t,Map<String,String> changed){TeacherChangeRequest request=new TeacherChangeRequest();List<TeacherChangeItem> items=new ArrayList<>();changed.forEach((field,value)->{TeacherChangeItem item=new TeacherChangeItem();item.setFieldName(field);item.setOldValue(showInput(read(t,field)));item.setNewValue(value);items.add(item);});request.setItems(items);service.submit(request,m->Platform.runLater(()->{statusLabel.setText(m.getMessage());if(ok(m)){editing=false;service.overview(this::receiveOverview);}}));}
 private boolean isAdmin(){String r=ClientSession.getInstance().getRole();return "ADMIN".equalsIgnoreCase(r)||"管理员".equals(r);} private boolean ok(Message m){return m!=null&&m.getCode()==MessageCode.SUCCESS;} private<T>T data(Message m,String k,Type t){return gson.fromJson(gson.toJson(m.getData().get(k)),t);} private SimpleStringProperty s(Object v){return new SimpleStringProperty(show(v));}
 private Object read(Teacher t,String f){try{String x=Character.toUpperCase(f.charAt(0))+f.substring(1);try{return Teacher.class.getMethod("get"+x).invoke(t);}catch(NoSuchMethodException e){return Teacher.class.getMethod("is"+x).invoke(t);}}catch(Exception e){return null;}}
 private void write(Teacher t,String f,String v){try{Field field=Teacher.class.getDeclaredField(f);String x=Character.toUpperCase(f.charAt(0))+f.substring(1);Method m=Arrays.stream(Teacher.class.getMethods()).filter(z->z.getName().equals("set"+x)).findFirst().orElseThrow();Object q=field.getType()==boolean.class?Set.of("是","true","1","在职").contains(v):field.getType()==Date.class?(v.isBlank()?null:Date.valueOf(v)):v.trim();m.invoke(t,q);}catch(Exception e){throw new IllegalArgumentException(f);}}
 private List<String> concat(List<String>...xs){List<String>o=new ArrayList<>();for(List<String>x:xs)o.addAll(x);return o;} private String show(Object v){if(v==null||String.valueOf(v).isBlank())return "-";return v instanceof Boolean?((Boolean)v?"是":"否"):String.valueOf(v);}private String showInput(Object v){if(v==null)return "";return v instanceof Boolean?((Boolean)v?"是":"否"):String.valueOf(v);}
 private String title(String f){return Map.ofEntries(Map.entry("UID","用户名"),Map.entry("teacherId","工号"),Map.entry("name","姓名"),Map.entry("politicalStatus","政治面貌"),Map.entry("nationality","民族"),Map.entry("gender","性别"),Map.entry("idType","身份证件类型"),Map.entry("idNumber","身份证号"),Map.entry("idIssueDate","身份证签发日期"),Map.entry("birthDate","出生日期"),Map.entry("nativePlace","籍贯"),Map.entry("householdType","户口性质"),Map.entry("birthPlace","出生地"),Map.entry("sourcePlace","生源地"),Map.entry("registeredResidence","户口所在地"),Map.entry("partyMember","是否党员"),Map.entry("partyJoinDate","入党时间"),Map.entry("healthStatus","健康状况"),Map.entry("employed","是否在职"),Map.entry("employmentStatus","任职状态"),Map.entry("campus","校区"),Map.entry("college","学院"),Map.entry("department","部门"),Map.entry("title","职称"),Map.entry("position","职务"),Map.entry("education","学历"),Map.entry("employmentStartDate","入职日期"),Map.entry("telephone","联系电话"),Map.entry("mobile","手机号"),Map.entry("email","电子邮箱"),Map.entry("qq","QQ号"),Map.entry("wechat","微信号"),Map.entry("officeAddress","在校办公地址"),Map.entry("emergencyContact","紧急联系人"),Map.entry("emergencyPhone","紧急联系人联系方式")).getOrDefault(f,f);}
